package com.nexusdrive.metadata.controller;import com.nexusdrive.common.dto.ApiResponse;import com.nexusdrive.common.security.CustomUserDetails;import com.nexusdrive.metadata.dto.FileResponse;import com.nexusdrive.metadata.entity.FileMetadata;import com.nexusdrive.metadata.repository.FileMetadataRepository;import io.swagger.v3.oas.annotations.Operation;import jakarta.persistence.criteria.Predicate;import java.time.Instant;import java.util.*;import org.springframework.data.domain.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/search")public class SearchController{private final FileMetadataRepository repo;public SearchController(FileMetadataRepository r){repo=r;}@Operation(summary="Search files with facets and pagination")@GetMapping public ApiResponse<Page<FileResponse>> search(@AuthenticationPrincipal CustomUserDetails user,@RequestParam(defaultValue="")String q,@RequestParam(required=false)String type,@RequestParam(required=false)UUID owner,@RequestParam(required=false)Instant dateFrom,@RequestParam(required=false)Instant dateTo,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){UUID effective="ADMIN".equals(user.role())?owner:user.userId();Page<FileMetadata> result=repo.findAll((root,query,cb)->{List<Predicate> p=new ArrayList<>();p.add(cb.equal(root.get("status"),FileMetadata.Status.ACTIVE));if(effective!=null)p.add(cb.equal(root.get("ownerId"),effective));if(!q.isBlank()){String like="%"+q.toLowerCase()+"%";var tags=cb.function("array_to_string",String.class,root.get("tags"),cb.literal(" "));p.add(cb.or(cb.like(cb.lower(root.get("filename")),like),cb.like(cb.lower(root.get("mimeType")),like),cb.like(cb.lower(tags),like)));}if(type!=null)p.add(cb.equal(root.get("mimeType"),type));if(dateFrom!=null)p.add(cb.greaterThanOrEqualTo(root.get("createdAt"),dateFrom));if(dateTo!=null)p.add(cb.lessThanOrEqualTo(root.get("createdAt"),dateTo));return cb.and(p.toArray(Predicate[]::new));},PageRequest.of(page,Math.min(Math.max(size,1),100),Sort.by(Sort.Direction.DESC,"createdAt")));return ApiResponse.ok(result.map(FileResponse::from));}}
